1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioOutcome = {
13	  results: StepResult[];
14	};
15	
16	type Item = { type: string; cursed?: boolean; enchantment?: number };
17	
18	type Customer = { yearsWithMHPCO: number };
19	
20	/** The policy-scope context a quote is priced in: who is buying, and whether
21	 * this is their first contract or a follow-up. */
22	type Policy = { customer: Customer; isFollowUpContract: boolean };
23	
24	type Damage = { itemType: string; amount: number };
25	
26	type Incident = { cause: string; damages: Damage[] };
27	
28	type QuoteStep = { op: string; items: Item[] };
29	
30	type ClaimStep = { op: string; policy: number; incident: Incident };
31	
32	type Step = QuoteStep | ClaimStep;
33	
34	const isQuoteStep = (step: Step): step is QuoteStep => step.op === "quote";
35	
36	type Scenario = {
37	  customer: Customer;
38	  steps: Step[];
39	};
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	const CURSE_SURCHARGE = 0.5;
44	const SURCHARGED_ENCHANTMENT_THRESHOLD = 5;
45	const ENCHANTMENT_SURCHARGE = 0.3;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
49	
50	const BASE_PREMIUMS: Record<string, number> = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	};
58	
59	const INSURANCE_VALUES: Record<string, number> = {
60	  sword: 1000,
61	  amulet: 600,
62	  rune: 250,
63	};
64	
65	const DEDUCTIBLE_PER_DAMAGE = 100;
66	const HALVED_ENCHANTMENT_THRESHOLD = 8;
67	const HALVED_REIMBURSEMENT = 0.5;
68	const FULL_REIMBURSEMENT = 1;
69	const CAP_MULTIPLIER = 2;
70	
71	const ALIKE_BLOCK_SIZE = 3;
72	const ALIKE_BLOCK_PREMIUM = 60;
73	
74	type AlikeGroup = [type: string, count: number];
75	
76	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
77	  const countByType = new Map<string, number>();
78	
79	  for (const item of items) {
80	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
81	  }
82	
83	  return [...countByType];
84	};
85	
86	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
87	
88	const ownBasePremiumOf = (item: Item): number => basePremiumOfType(item.type);
89	
90	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
91	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
92	
93	  return count * basePremiumOfType(type);
94	};
95	
96	/**
97	 * The policy base premium: the sum of the item base premiums, with the
98	 * alike-block discount applied. Policy-scope modifiers are percentages OF
99	 * THIS amount — never of a total that already includes item surcharges.
100	 */
101	const policyBasePremiumOf = (items: Item[]): number =>
102	  groupAlikeItems(items)
103	    .map(basePremiumOfGroup)
104	    .reduce((total, groupPremium) => total + groupPremium, 0);
105	
106	/**
107	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
108	 * premium, independent of the policy base and of the alike-block discount.
109	 */
110	const isCursed = (item: Item): boolean => item.cursed === true;
111	
112	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
113	
114	const carriesEnchantmentSurcharge = (item: Item): boolean =>
115	  enchantmentOf(item) >= SURCHARGED_ENCHANTMENT_THRESHOLD;
116	
117	const itemSurchargeRateOf = (item: Item): number =>
118	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
119	  (carriesEnchantmentSurcharge(item) ? ENCHANTMENT_SURCHARGE : 0);
120	
121	const itemSurchargesOf = (items: Item[]): number =>
122	  items.reduce(
123	    (total, item) => total + ownBasePremiumOf(item) * itemSurchargeRateOf(item),
124	    0,
125	  );
126	
127	/**
128	 * Policy-scope modifiers: each is a percentage of the policy base premium.
129	 * Surcharges and discounts are netted into a single rate, so the policy base is
130	 * multiplied exactly once — this keeps the result free of the rounding drift
131	 * that separate discount and surcharge terms would introduce. The netted rate
132	 * (and hence the returned amount) is negative when the discounts outweigh the
133	 * surcharges.
134	 */
135	const isLongStanding = (customer: Customer): boolean =>
136	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
137	
138	const policyModifierRateOf = ({ customer, isFollowUpContract }: Policy): number =>
139	  FIRST_INSURANCE_SURCHARGE -
140	  (isLongStanding(customer) ? LOYALTY_DISCOUNT : 0) -
141	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
142	
143	const policyModifiersOn = (policyBase: number, policy: Policy): number =>
144	  policyBase * policyModifierRateOf(policy);
145	
146	const quotePremium = (items: Item[], policy: Policy): number => {
147	  const policyBase = policyBasePremiumOf(items);
148	  const premium =
149	    policyBase +
150	    itemSurchargesOf(items) +
151	    policyModifiersOn(policyBase, policy) +
152	    PROCESSING_FEE;
153	
154	  return Math.ceil(premium);
155	};
156	
157	/**
158	 * Whether any step precedes this one. A quote is a follow-up contract when the
159	 * customer already holds one, and today every step is a quote — so "has a
160	 * predecessor" and "is a follow-up contract" coincide.
161	 *
162	 * They stop coinciding once claim steps exist: a claim at index 0 would make
163	 * the quote at index 1 look like a follow-up. At that point the caller must
164	 * count preceding QUOTE steps instead of asking this. The name is deliberately
165	 * about position, not contracts, so that the substitution is a visible change
166	 * at the call site rather than a silent redefinition here.
167	 */
168	const hasPrecedingStep = (stepIndex: number): boolean => stepIndex > 0;
169	
170	const insuranceSumOf = (items: Item[]): number =>
171	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
172	
173	const isReimbursedByHalf = (item: Item): boolean =>
174	  enchantmentOf(item) >= HALVED_ENCHANTMENT_THRESHOLD;
175	
176	/**
177	 * The share of a damage amount that is reimbursed, before the deductible.
178	 *
179	 * The specification's dragon-material rule ("damage to items made of dragon
180	 * material is fully reimbursed") is deliberately ABSENT here, and `Item` has no
181	 * `material` field. The rule is unobservable given the other rules:
182	 *
183	 * - Full reimbursement is already FULL_REIMBURSEMENT, the default rate, so on
184	 *   items below the halving threshold a dragon clause would compute what this
185	 *   function computes anyway.
186	 * - The only inputs where the two clauses disagree are items with enchantment
187	 *   >= HALVED_ENCHANTMENT_THRESHOLD, and there the spec awards the conflict to
188	 *   halving ("both clauses apply; the 50 % rule wins").
189	 *
190	 * So no input distinguishes an implemented dragon clause from this one. The
191	 * spec's own examples confirm it: a steel sword and a dragon sword at
192	 * enchantment 9 with 1000 G damage both pay out 400 G. Implementing it would
193	 * add an unreachable branch and a field nothing reads.
194	 *
195	 * This stops holding the moment dragon material gains an effect OUTSIDE the
196	 * reimbursement rate — a different deductible, or an exemption from the payout
197	 * cap. Such a rule would need a real `material` field and a real branch.
198	 */
199	const reimbursementRateFor = (item: Item): number =>
200	  isReimbursedByHalf(item) ? HALVED_REIMBURSEMENT : FULL_REIMBURSEMENT;
201	
202	/**
203	 * The insured item a damage entry refers to. Shares the assumption documented
204	 * on `policyReferencedBy`: the damaged type is ASSUMED to be insured, and a
205	 * damage naming an uninsured or unknown type fails downstream with an opaque
206	 * undefined-property error rather than a rejection. The pending
207	 * error-handling tests are what will force a real rejection here.
208	 */
209	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
210	  items.find(({ type }) => type === damage.itemType) as Item;
211	
212	/**
213	 * A single damage entry settles in two stages, in this order: the reimbursement
214	 * rate applies to the damage amount, and the deductible comes off the result.
215	 * The spec is explicit that the sequencing matters ("the 50 % rule wins, then
216	 * deductible"), so it is spelled out rather than left to operator precedence.
217	 */
218	const payoutForDamage = (damage: Damage, items: Item[]): number => {
219	  const reimbursed =
220	    damage.amount * reimbursementRateFor(insuredItemFor(damage, items));
221	
222	  return reimbursed - DEDUCTIBLE_PER_DAMAGE;
223	};
224	
225	/**
226	 * The quote step a claim is filed against. Today this ASSUMES the referenced
227	 * index holds a quote: nothing has forced the assumption to be checked yet, and
228	 * a claim naming a non-quote step fails here with an opaque undefined-property
229	 * error rather than a rejection.
230	 *
231	 * The assumption is isolated in this function on purpose. The pending
232	 * error-handling tests ("a claim for an item not part of the policy", "a claim
233	 * with a damage entry of an unknown item type") are what will force a real
234	 * rejection, and this is the single place that has to change when they do.
235	 */
236	const policyReferencedBy = (claim: ClaimStep, steps: Step[]): QuoteStep =>
237	  steps[claim.policy] as QuoteStep;
238	
239	const settleClaim = (
240	  claim: ClaimStep,
241	  steps: Step[],
242	  capRemainingByPolicy: Map<number, number>,
243	): ClaimResult => {
244	  const policy = policyReferencedBy(claim, steps);
245	  const capRemaining =
246	    capRemainingByPolicy.get(claim.policy) ??
247	    CAP_MULTIPLIER * insuranceSumOf(policy.items);
248	  const claimed = claim.incident.damages.reduce(
249	    (total, damage) => total + payoutForDamage(damage, policy.items),
250	    0,
251	  );
252	  const payout = Math.min(claimed, capRemaining);
253	  const remainingCap = capRemaining - payout;
254	
255	  capRemainingByPolicy.set(claim.policy, remainingCap);
256	
257	  return { payout, remainingCap };
258	};
259	
260	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
261	  const capRemainingByPolicy = new Map<number, number>();
262	
263	  return {
264	    results: scenario.steps.map((step, stepIndex) =>
265	      isQuoteStep(step)
266	        ? {
267	            premium: quotePremium(step.items, {
268	              customer: scenario.customer,
269	              isFollowUpContract: hasPrecedingStep(stepIndex),
270	            }),
271	          }
272	        : settleClaim(step, scenario.steps, capRemainingByPolicy),
273	    ),
274	  };
275	};
