const settleClaim = (
  claim: ClaimStep,
  steps: Step[],
  capRemainingByPolicy: Map<number, number>,
): ClaimResult => {
  const policy = policyReferencedBy(claim, steps);
  const capRemaining =
    capRemainingByPolicy.get(claim.policy) ??
    CAP_MULTIPLIER * insuranceSumOf(policy.items);
  const claimed = claim.incident.damages.reduce(
    (total, damage) => total + payoutForDamage(damage, policy.items),
    0,
  );
  const payout = Math.min(claimed, capRemaining);
  const remainingCap = capRemaining - payout;

  capRemainingByPolicy.set(claim.policy, remainingCap);

  return { payout, remainingCap };
};

